async function (variables) {
    var roleGrid = new GridWidget(variables.element, variables.dataSource);
    roleGrid.editable = false;
    roleGrid.groupable = false;
    roleGrid.pageable = false;
    roleGrid.change = function (e) {
        var selectedRows = this.select();
        variables.SelectedCoreRoles = [];
        for (var i = 0; i < selectedRows.length; i++) {
            var dataItem = this.dataItem(selectedRows[i]);
            variables.SelectedCoreRoles.push(dataItem);
        }
    };
    roleGrid.sortable = true;
    roleGrid.filterable = true;
    roleGrid.columns =
        [{ selectable: (variables.readonly) ? false : true, width: "50px" },
        { field: "Name", title: "[resource_shortdisplayname[name]]" }
        ];
    variables.CoreRoleGrid = roleGrid;
}
